323:
SELECT m."label"
FROM "molecule" m
WHERE m."molecule_id" = 'TR000';

319:
SELECT COUNT(DISTINCT c."atom_id") AS element_count
FROM "connected" c
WHERE c."bond_id" = 'TR001_3_4';

699:
SELECT u."creationdate"
FROM "users" AS u
WHERE u."displayname" LIKE '%IrishStat%';

588:
SELECT COUNT(*) AS total_comments
FROM comments c
WHERE c.userid = 13;

572:
SELECT p."viewcount"
FROM "posts" p
WHERE p."title" LIKE '%Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer%';

745:
SELECT p."id"
FROM "publisher" AS p
WHERE p."publisher_name" LIKE '%Star Trek%';

803:
SELECT sp.id
FROM superpower sp
WHERE sp.power_name = 'cryokinesis';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(*) AS president_count
FROM "member" m
WHERE LOWER(m."position") LIKE '%president%';

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
    SELECT MIN("remaining") FROM "budget"
);
